attribute vec3 aO, aV; attribute vec2 aT; attribute float aC; uniform float uTime; varying vec2 vUv; varying float vF; varying float vC;
    void main(){
      float age = uTime - aT.x; if (age < 0. || age > aT.y){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = 3., e = exp(-k*age); vec3 p = aO + aV*(1.-e)/k; p.y -= .3*9.8*(age*age*.5);
      float f = 1. - age/aT.y, sz = .09*(.4 + .6*f), rot = aC*3. + age*9.;
      vec4 mv = viewMatrix*vec4(p,1.); vec2 q = position.xy; q = vec2(cos(rot)*q.x - sin(rot)*q.y, sin(rot)*q.x + cos(rot)*q.y);
      mv.xy += q*vec2(sz*.9, sz*1.8); gl_Position = projectionMatrix*mv; vUv = position.xy; vF = f; vC = step(.5, fract(aC));
    }

